package com.jnapanam.sportszone.payment.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="payment_webhook_events")public class PaymentWebhookEvent{@Id private UUID id;@Column(name="provider_event_id",nullable=false,unique=true,length=160)private String providerEventId;@Column(name="event_type",nullable=false,length=80)private String eventType;@Column(name="payload_hash",nullable=false,length=64)private String payloadHash;@Column(nullable=false,length=20)private String status;@Column(name="processed_at",nullable=false)private Instant processedAt;protected PaymentWebhookEvent(){}public PaymentWebhookEvent(String eventId,String type,String hash){id=UUID.randomUUID();providerEventId=eventId;eventType=type;payloadHash=hash;status="PROCESSED";processedAt=Instant.now();}}
